  ".dsh-wt_flowEdit{flex:1 1 100%;display:flex;flex-direction:column;gap:6px;margin-top:2px;padding-top:7px;border-top:1px dashed var(--dsw-alias-border-l1,#262b36)}",
  ".dsh-wt_flowEditRow{display:flex;flex-direction:column;gap:3px}",
