  ".dsh-wt_flowAccToggle:hover{color:var(--dsw-alias-label-primary,#e6edf3)}",
  ".dsh-wt_flowAccBody{margin-top:4px;display:flex;flex-direction:column;gap:6px;border-left:2px solid var(--dsw-alias-fill-l2,rgba(255,255,255,.1));padding-left:8px}",
