      "position:fixed",
      "left:12px",
      "right:12px",
      "top:calc(env(safe-area-inset-top, 0px) + 12px)",
      "z-index:2147483000",
      "padding:10px 14px",
      "border-radius:12px",
      "background:#1f2937",
      "color:#f9fafb",
      "font-size:13px",
      "line-height:1.45",
      "box-shadow:0 8px 24px rgba(0,0,0,.28)",
      "text-align:center"
